codeExamples.tech1Snippet:
const Database = require('better-sqlite3');
const db = new Database('hello.db');
db.exec('CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY, text TEXT NOT NULL)');
db.prepare('INSERT INTO messages (text) VALUES (?)').run('Hello, World!');
console.log(db.prepare('SELECT text FROM messages ORDER BY id DESC LIMIT 1').get());

