const Memcached = require('memcached');
const client = new Memcached('127.0.0.1:11211');
client.set('greeting', 'Hello, World!', 60, (err) => {
  if (err) throw err;
  client.get('greeting', (err, data) => {
    if (err) throw err;
    console.log(data);
    client.end();
  });
});
